    'a0000000-0000-0000-0000-000000000002|b0000000-0000-0000-0000-000000000005|b0000000-0000-0000-0000-000000000006|b0000000-0000-0000-0000-000000000007|c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000004|c0000000-0000-0000-0000-000000000019|b0000000-0000-0000-0000-000000000019|a0000000-0000-0000-0000-000000000014|a0000000-0000-0000-0000-000000000015|d0000000-0000-0000-0000-000000000001|e0000000-0000-0000-0000-000000000012|e0000000-0000-0000-0000-000000000011|f0000000-0000-0000-0000-000000000006|f0000000-0000-0000-0000-000000000010|b0000000-0000-0000-0000-000000000008|c0000000-0000-0000-0000-000000000018|f2000000-0000-0000-0000-000000000012|e0000000-0000-0000-0000-000000000025|d0000000-0000-0000-0000-000000000030',
    -- 32: Frontend Next.js (variant)
    'a0000000-0000-0000-0000-000000000002|b0000000-0000-0000-0000-000000000003|b0000000-0000-0000-0000-000000000004|b0000000-0000-0000-0000-000000000019|a0000000-0000-0000-0000-000000000014|a0000000-0000-0000-0000-000000000015|b0000000-0000-0000-0000-000000000050|b0000000-0000-0000-0000-000000000051|e0000000-0000-0000-0000-000000000011|e0000000-0000-0000-0000-000000000012|d0000000-0000-0000-0000-000000000030|f2000000-0000-0000-0000-000000000012|f2000000-0000-0000-0000-000000000005|f2000000-0000-0000-0000-000000000013|e0000000-0000-0000-0000-000000000025|e0000000-0000-0000-0000-000000000021|c0000000-0000-0000-0000-000000000015|c0000000-0000-0000-0000-000000000001|f0000000-0000-0000-0000-000000000006|d0000000-0000-0000-0000-000000000001',
    -- 33: Backend Go (variant)
    'a0000000-0000-0000-0000-000000000007|b0000000-0000-0000-0000-000000000065|b0000000-0000-0000-0000-000000000066|c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000004|c0000000-0000-0000-0000-000000000003|d0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000003|f0000000-0000-0000-0000-000000000006|f0000000-0000-0000-0000-000000000008|f0000000-0000-0000-0000-000000000010|f2000000-0000-0000-0000-000000000009|f2000000-0000-0000-0000-000000000007|a0000000-0000-0000-0000-000000000024|d0000000-0000-0000-0000-000000000012|d0000000-0000-0000-0000-000000000010|e0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000004|c0000000-0000-0000-0000-000000000016|f2000000-0000-0000-0000-000000000006',
    -- 34: DevOps Azure (variant)
    'd0000000-0000-0000-0000-000000000005|d0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000003|d0000000-0000-0000-0000-000000000010|d0000000-0000-0000-0000-000000000012|d0000000-0000-0000-0000-000000000009|d0000000-0000-0000-0000-000000000023|d0000000-0000-0000-0000-000000000013|d0000000-0000-0000-0000-000000000014|d0000000-0000-0000-0000-000000000015|a0000000-0000-0000-0000-000000000024|a0000000-0000-0000-0000-000000000025|a0000000-0000-0000-0000-000000000003|c0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000019|d0000000-0000-0000-0000-000000000011|d0000000-0000-0000-0000-000000000002|f0000000-0000-0000-0000-000000000020|e0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000016',
    -- 35: Mobile Android (variant)
    'a0000000-0000-0000-0000-000000000011|b0000000-0000-0000-0000-000000000049|a0000000-0000-0000-0000-000000000002|b0000000-0000-0000-0000-000000000017|b0000000-0000-0000-0000-000000000018|c0000000-0000-0000-0000-000000000010|c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000015|e0000000-0000-0000-0000-000000000012|d0000000-0000-0000-0000-000000000001|f0000000-0000-0000-0000-000000000006|f0000000-0000-0000-0000-000000000010|e0000000-0000-0000-0000-000000000028|a0000000-0000-0000-0000-000000000004|e0000000-0000-0000-0000-000000000021|a0000000-0000-0000-0000-000000000012|a0000000-0000-0000-0000-000000000001|f2000000-0000-0000-0000-000000000004|e0000000-0000-0000-0000-000000000001|b0000000-0000-0000-0000-000000000003',
    -- 36: ML Ops (variant)
    'a0000000-0000-0000-0000-000000000003|b0000000-0000-0000-0000-000000000061|b0000000-0000-0000-0000-000000000062|d0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000003|d0000000-0000-0000-0000-000000000004|d0000000-0000-0000-0000-000000000010|f2000000-0000-0000-0000-000000000001|f2000000-0000-0000-0000-000000000027|c0000000-0000-0000-0000-000000000001|a0000000-0000-0000-0000-000000000024|d0000000-0000-0000-0000-000000000014|d0000000-0000-0000-0000-000000000008|f2000000-0000-0000-0000-000000000019|f2000000-0000-0000-0000-000000000025|b0000000-0000-0000-0000-000000000059|b0000000-0000-0000-0000-000000000060|e0000000-0000-0000-0000-000000000001|a0000000-0000-0000-0000-000000000013|d0000000-0000-0000-0000-000000000012',
    -- 37: Infra Engineer (variant)
    'd0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000002|d0000000-0000-0000-0000-000000000003|d0000000-0000-0000-0000-000000000011|d0000000-0000-0000-0000-000000000022|d0000000-0000-0000-0000-000000000012|d0000000-0000-0000-0000-000000000013|d0000000-0000-0000-0000-000000000021|a0000000-0000-0000-0000-000000000024|a0000000-0000-0000-0000-000000000025|a0000000-0000-0000-0000-000000000007|c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000004|d0000000-0000-0000-0000-000000000004|d0000000-0000-0000-0000-000000000010|d0000000-0000-0000-0000-000000000007|d0000000-0000-0000-0000-000000000019|e0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000014|d0000000-0000-0000-0000-000000000015',
    -- 38: QA Performance (variant)
    'e0000000-0000-0000-0000-000000000012|b0000000-0000-0000-0000-000000000054|b0000000-0000-0000-0000-000000000055|f0000000-0000-0000-0000-000000000003|a0000000-0000-0000-0000-000000000002|a0000000-0000-0000-0000-000000000007|d0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000007|d0000000-0000-0000-0000-000000000014|d0000000-0000-0000-0000-000000000015|e0000000-0000-0000-0000-000000000005|e0000000-0000-0000-0000-000000000027|c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000004|a0000000-0000-0000-0000-000000000024|f0000000-0000-0000-0000-000000000011|e0000000-0000-0000-0000-000000000008|a0000000-0000-0000-0000-000000000001|b0000000-0000-0000-0000-000000000007|f0000000-0000-0000-0000-000000000006',
    -- 39: Arquiteto Dados (variant)
    'c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000003|c0000000-0000-0000-0000-000000000009|a0000000-0000-0000-0000-000000000003|a0000000-0000-0000-0000-000000000013|f2000000-0000-0000-0000-000000000025|f2000000-0000-0000-0000-000000000026|f2000000-0000-0000-0000-000000000027|f2000000-0000-0000-0000-000000000028|f0000000-0000-0000-0000-000000000004|f0000000-0000-0000-0000-000000000009|d0000000-0000-0000-0000-000000000004|d0000000-0000-0000-0000-000000000001|f2000000-0000-0000-0000-000000000008|f2000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000008|c0000000-0000-0000-0000-000000000016|e0000000-0000-0000-0000-000000000001|f0000000-0000-0000-0000-000000000010|d0000000-0000-0000-0000-000000000010',
    -- 40: Tech Lead Backend (variant)
    'a0000000-0000-0000-0000-000000000002|a0000000-0000-0000-0000-000000000007|b0000000-0000-0000-0000-000000000007|b0000000-0000-0000-0000-000000000013|c0000000-0000-0000-0000-000000000001|c0000000-0000-0000-0000-000000000004|d0000000-0000-0000-0000-000000000001|d0000000-0000-0000-0000-000000000003|f0000000-0000-0000-0000-000000000004|f1000000-0000-0000-0000-000000000003|f1000000-0000-0000-0000-000000000009|f0000000-0000-0000-0000-000000000008|f0000000-0000-0000-0000-000000000009|f0000000-0000-0000-0000-000000000010|e0000000-0000-0000-0000-000000000001|e0000000-0000-0000-0000-000000000027|f1000000-0000-0000-0000-000000000017|f1000000-0000-0000-0000-000000000020|f0000000-0000-0000-0000-000000000006|f2000000-0000-0000-0000-000000000007'
  ];

  pool_arr TEXT[];
  pool_size INT;
  levels TEXT[] := ARRAY['beginner', 'intermediate', 'advanced', 'expert'];

  -- Salary ranges by seniority [min_base, max_base]
  salary_jr_min INT := 2000;  salary_jr_max INT := 5000;
  salary_pl_min INT := 5000;  salary_pl_max INT := 10000;
  salary_sr_min INT := 10000; salary_sr_max INT := 22000;

  role_family TEXT;
  title_text TEXT;
BEGIN
  FOR i IN 1..200000 LOOP
    role_idx := ((i - 1) % 40) + 1;
    seniority_idx := ((i - 1) % 3) + 1; -- 1=jr, 2=pl, 3=sr
    city_idx := ((i - 1) % 150) + 1;

    user_uuid    := ('10000000-0000-0000-0001-' || lpad(i::text, 12, '0'))::uuid;
    profile_uuid := ('10000000-0000-0000-0002-' || lpad(i::text, 12, '0'))::uuid;

    role_family := role_families[role_idx];
    title_text := role_family || ' ' || seniority_titles[seniority_idx];
    dev_handle := 'dev-' || lpad(i::text, 6, '0');
    dev_email := 'dev' || i || '@devport.test';
    dev_full_name := title_text || ' #' || i;
    dev_bio := 'Profissional ' || seniority_names[seniority_idx] || ' em ' || role_family || '. Experiência sólida em desenvolvimento de software.';
    dev_work_modes := work_mode_combos[((i - 1) % 6) + 1];
    dev_emp_status := emp_statuses[((i - 1) % 4) + 1];
    dev_city := cities[city_idx];

    -- Salary consistent with seniority + variation (CLT base)
    IF seniority_idx = 1 THEN
      dev_salary_clt_min := salary_jr_min + (i % 8) * 200;
      dev_salary_clt_max := dev_salary_clt_min + 1500 + (i % 5) * 300;
    ELSIF seniority_idx = 2 THEN
      dev_salary_clt_min := salary_pl_min + (i % 10) * 300;
      dev_salary_clt_max := dev_salary_clt_min + 2500 + (i % 6) * 400;
    ELSE
      dev_salary_clt_min := salary_sr_min + (i % 12) * 500;
      dev_salary_clt_max := dev_salary_clt_min + 4000 + (i % 8) * 600;
    END IF;

    -- ~50% of devs also have PJ salary (CLT * 1.4 approximation)
    IF i % 2 = 0 THEN
      dev_salary_pj_min := ROUND(dev_salary_clt_min * 1.4);
      dev_salary_pj_max := ROUND(dev_salary_clt_max * 1.4);
    ELSE
      dev_salary_pj_min := NULL;
      dev_salary_pj_max := NULL;
    END IF;

    -- ~20% have no CLT salary (PJ only)
    IF i % 5 = 0 THEN
      dev_salary_pj_min := COALESCE(dev_salary_pj_min, ROUND(dev_salary_clt_min * 1.4));
      dev_salary_pj_max := COALESCE(dev_salary_pj_max, ROUND(dev_salary_clt_max * 1.4));
      dev_salary_clt_min := NULL;
      dev_salary_clt_max := NULL;
    END IF;

    -- Radius: ~60% have a preference, rest NULL (use default)
    IF i % 5 <= 2 THEN
      dev_max_radius := 10 + (i % 51); -- 10-60 km
    ELSE
      dev_max_radius := NULL;
    END IF;

    -- User
    INSERT INTO users (id, name, email, password_hash, role)
    VALUES (user_uuid, dev_full_name, dev_email, pw_hash, 'dev')
    ON CONFLICT (id) DO NOTHING;

    -- Profile
    INSERT INTO dev_profiles (id, user_id, handle, full_name, title, bio, email_contact, city_id, work_modes, employment_status, salary_clt_min, salary_clt_max, salary_pj_min, salary_pj_max, max_radius_km)
    VALUES (profile_uuid, user_uuid, dev_handle, dev_full_name, title_text, dev_bio, dev_email, dev_city, dev_work_modes::jsonb, dev_emp_status, dev_salary_clt_min, dev_salary_clt_max, dev_salary_pj_min, dev_salary_pj_max, dev_max_radius)
    ON CONFLICT (id) DO NOTHING;

    -- =============================================
    -- SKILLS: 5-20 based on seniority
    -- Junior: 5-8 skills, mostly beginner/intermediate
    -- Pleno: 8-14 skills, intermediate/advanced
    -- Senior: 12-20 skills, advanced/expert
    -- =============================================

    pool_arr := string_to_array(skill_pools[role_idx], '|');
    pool_size := array_length(pool_arr, 1);

    IF seniority_idx = 1 THEN
      num_skills := 5 + (i % 4); -- 5-8
    ELSIF seniority_idx = 2 THEN
      num_skills := 8 + (i % 7); -- 8-14
    ELSE
      num_skills := 12 + (i % 9); -- 12-20
    END IF;

    IF num_skills > pool_size THEN
      num_skills := pool_size;
    END IF;

    skill_counter := 0;
    FOR j IN 1..num_skills LOOP
      -- Rotate starting position per dev for variety within same role
      sk_id := pool_arr[((i + j - 1) % pool_size) + 1];
      skill_counter := skill_counter + 1;

      -- Level depends on seniority + position in skill list
      -- First skills = strongest, last = weaker
      IF seniority_idx = 3 THEN
        -- Senior: first 5 expert, next 5 advanced, rest intermediate
        IF j <= 5 THEN sk_level := 'expert';
        ELSIF j <= 10 THEN sk_level := 'advanced';
        ELSE sk_level := 'intermediate';
        END IF;
      ELSIF seniority_idx = 2 THEN
        -- Pleno: first 3 advanced, next 5 intermediate, rest beginner
        IF j <= 3 THEN sk_level := 'advanced';
        ELSIF j <= 8 THEN sk_level := 'intermediate';
        ELSE sk_level := 'beginner';
        END IF;
      ELSE
        -- Junior: first 2 intermediate, rest beginner
        IF j <= 2 THEN sk_level := 'intermediate';
        ELSE sk_level := 'beginner';
        END IF;
      END IF;

      INSERT INTO dev_skills (id, dev_profile_id, skill_id, level, years_experience)
      VALUES (
        ('10000000-0000-0000-0003-' || lpad((i * 100 + skill_counter)::text, 12, '0'))::uuid,
        profile_uuid,
        sk_id::uuid,
        sk_level,
        CASE
          WHEN seniority_idx = 1 THEN (j % 2) + 1       -- 1-2 years
          WHEN seniority_idx = 2 THEN (j % 3) + 2       -- 2-4 years
          ELSE (j % 4) + 4                                -- 4-7 years
        END
      )
      ON CONFLICT DO NOTHING;
    END LOOP;

    -- Always add Git + Scrum (common)
    INSERT INTO dev_skills (id, dev_profile_id, skill_id, level, years_experience)
    VALUES
      (('10000000-0000-0000-0003-' || lpad((i * 100 + 90)::text, 12, '0'))::uuid, profile_uuid,
       'e0000000-0000-0000-0000-000000000001',
       CASE WHEN seniority_idx = 3 THEN 'expert' WHEN seniority_idx = 2 THEN 'advanced' ELSE 'intermediate' END,
       seniority_idx * 2),
      (('10000000-0000-0000-0003-' || lpad((i * 100 + 91)::text, 12, '0'))::uuid, profile_uuid,
       'f0000000-0000-0000-0000-000000000001',
       CASE WHEN seniority_idx = 3 THEN 'advanced' ELSE 'intermediate' END,
       seniority_idx)
    ON CONFLICT DO NOTHING;

    -- =============================================
    -- EXPERIENCES: 1-4 based on seniority
    -- Junior: 1 exp (current, 1-2 years)
    -- Pleno: 2 exp (current + 1 previous)
    -- Senior: 3-4 exp (current + 2-3 previous)
    -- =============================================

    -- Current job
    exp_uuid := ('10000000-0000-0000-0004-' || lpad((i * 10 + 1)::text, 12, '0'))::uuid;
    exp_company := companies[((i - 1) % 30) + 1];

    IF seniority_idx = 1 THEN
      exp_start := ('2024-01-01'::date + ((i % 12) || ' months')::interval)::date;
    ELSIF seniority_idx = 2 THEN
      exp_start := ('2022-01-01'::date + ((i % 18) || ' months')::interval)::date;
    ELSE
      exp_start := ('2020-01-01'::date + ((i % 24) || ' months')::interval)::date;
    END IF;

    INSERT INTO experiences (id, dev_profile_id, company, position, description, start_date, is_current)
    VALUES (exp_uuid, profile_uuid, exp_company, title_text,
            'Atuação como ' || title_text || ' em projetos de desenvolvimento.',
            exp_start, true)
    ON CONFLICT (id) DO NOTHING;

    -- Previous experiences
    IF seniority_idx >= 2 THEN
      exp_uuid := ('10000000-0000-0000-0004-' || lpad((i * 10 + 2)::text, 12, '0'))::uuid;
      exp_company := companies[((i + 7) % 30) + 1];
      exp_start := ('2019-01-01'::date + ((i % 12) || ' months')::interval)::date;
      exp_end := exp_start + '2 years'::interval;

      INSERT INTO experiences (id, dev_profile_id, company, position, description, start_date, end_date, is_current)
      VALUES (exp_uuid, profile_uuid, exp_company,
              role_family || ' ' || CASE WHEN seniority_idx = 3 THEN 'Pleno' ELSE 'Júnior' END,
              'Desenvolvimento de software e manutenção de sistemas.',
              exp_start, exp_end, false)
      ON CONFLICT (id) DO NOTHING;
    END IF;

    IF seniority_idx = 3 THEN
      exp_uuid := ('10000000-0000-0000-0004-' || lpad((i * 10 + 3)::text, 12, '0'))::uuid;
      exp_company := companies[((i + 14) % 30) + 1];
      exp_start := ('2016-01-01'::date + ((i % 18) || ' months')::interval)::date;
      exp_end := exp_start + '3 years'::interval;

      INSERT INTO experiences (id, dev_profile_id, company, position, description, start_date, end_date, is_current)
      VALUES (exp_uuid, profile_uuid, exp_company,
              role_family || ' Júnior',
              'Início de carreira em desenvolvimento de software.',
              exp_start, exp_end, false)
      ON CONFLICT (id) DO NOTHING;

      -- 50% of seniors get a 4th experience
      IF i % 2 = 0 THEN
        exp_uuid := ('10000000-0000-0000-0004-' || lpad((i * 10 + 4)::text, 12, '0'))::uuid;
        exp_company := companies[((i + 21) % 30) + 1];
        exp_start := ('2014-01-01'::date + ((i % 12) || ' months')::interval)::date;
        exp_end := exp_start + '2 years'::interval;

        INSERT INTO experiences (id, dev_profile_id, company, position, description, start_date, end_date, is_current)
        VALUES (exp_uuid, profile_uuid, exp_company,
                'Estagiário de Desenvolvimento',
                'Estágio em desenvolvimento de software.',
                exp_start, exp_end, false)
        ON CONFLICT (id) DO NOTHING;
      END IF;
    END IF;

  END LOOP;

  RAISE NOTICE 'Seed complete: 200000 devs with profiles, skills and experiences';
END $$;

